func parseFunctionHeader(line string) (*Function, error) {
	parenOpen := strings.Index(line, "(")
	parenClose := strings.LastIndex(line, ")")
	if parenOpen == -1 || parenClose == -1 || parenClose < parenOpen {
		return nil, errors.New("invalid function signature")
	}
	name := strings.TrimSpace(line[:parenOpen])
	argsStr := line[parenOpen+1 : parenClose]
	ret := strings.TrimSpace(line[parenClose+1:])

	args, err := parseArgs(argsStr)
	if err != nil {
		return nil, err
	}

	return &Function{
		Name:       name,
		Args:       args,
		ReturnType: ret,
	}, nil
}

func parseQueryHeader(line string) (*Query, error) {
	parenOpen := strings.Index(line, "(")
	if parenOpen == -1 {
		return &Query{Name: strings.TrimSpace(line)}, nil
	}
	parenClose := strings.LastIndex(line, ")")
	if parenClose == -1 || parenClose < parenOpen {
		return nil, errors.New("invalid query signature")
	}
	name := strings.TrimSpace(line[:parenOpen])
	argsStr := line[parenOpen+1 : parenClose]

	args, err := parseArgs(argsStr)
	if err != nil {
		return nil, err
	}

	return &Query{
		Name: name,
		Args: args,
	}, nil
}

func parseArgs(s string) ([]Argument, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, nil
	}
	parts := strings.Split(s, ",")
	var args []Argument
	for _, p := range parts {
		p = strings.TrimSpace(p)
		idx := strings.LastIndex(p, " ")
		if idx == -1 {
			return nil, fmt.Errorf("invalid argument format: %q", p)
		}
		name := strings.TrimSpace(p[:idx])
		typ := strings.TrimSpace(p[idx+1:])
		args = append(args, Argument{Name: name, Type: typ})
	}
	return args, nil
}
EOF

cat <<EOF >> /Users/sujit/Sites/scrt/src/schema.ts

function parseFunctionHeader(line: string): FunctionDef {
    const parenOpen = line.indexOf("(");
    const parenClose = line.lastIndexOf(")");
    if (parenOpen === -1 || parenClose === -1 || parenClose < parenOpen) {
        throw new Error("scrt: invalid function signature");
    }
    const name = line.slice(0, parenOpen).trim();
    const argsStr = line.slice(parenOpen + 1, parenClose);
    const ret = line.slice(parenClose + 1).trim();
    const args = parseArgs(argsStr);
    return new FunctionDef(name, args, ret);
}

function parseQueryHeader(line: string): QueryDef {
    const parenOpen = line.indexOf("(");
    if (parenOpen === -1) {
        return new QueryDef(line.trim(), []);
    }
    const parenClose = line.lastIndexOf(")");
    if (parenClose === -1 || parenClose < parenOpen) {
        throw new Error("scrt: invalid query signature");
    }
    const name = line.slice(0, parenOpen).trim();
    const argsStr = line.slice(parenOpen + 1, parenClose);
    const args = parseArgs(argsStr);
    return new QueryDef(name, args);
}

function parseArgs(str: string): Argument[] {
    const s = str.trim();
    if (!s) return [];
    const parts = s.split(",");
    const args: Argument[] = [];
    for (const p of parts) {
        const trimmed = p.trim();
        const idx = trimmed.lastIndexOf(" ");
        if (idx === -1) {
            throw new Error(\`scrt: invalid argument format: \${p}\`);
        }
        const name = trimmed.slice(0, idx).trim();
        const typ = trimmed.slice(idx + 1).trim();
        args.push({ name, type: typ });
    }
    return args;
}
EOF

